css:
.hst-nl{color-scheme:light;
    --teal:#4C9C87; --teal-dark:#3E8571; --teal-soft:#E4F1EC;
    --navy:#182543; --navy-2:#223257; --ink:#151B28; --slate:#5A6472;
    --line:#D5DAE2; --bg:#F6F7F9; --card:#FFFFFF; --amber:#E0A030;
scroll-behavior:smooth;
margin:0;background:var(--bg);color:var(--ink);font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:16px;line-height:1.6;-webkit-font-smoothing:antialiased;}
@scope (.hst-nl){
*{box-sizing:border-box;min-width:0}
a{color:var(--teal-dark);text-decoration:none;border-bottom:1px solid rgba(76,156,135,.4)}
a:hover{border-bottom-color:var(--teal-dark)}
h1, h2, h3, h4{margin:0;line-height:1.2;font-weight:800;color:var(--navy)}
p{margin:0 0 14px}
.wrap{max-width:1040px;margin:0 auto;padding:0 22px}
/* Header */
  .top{background:#fff;border-bottom:1px solid var(--line)}
.top .wrap{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:14px;padding-bottom:14px}
.logo{display:flex;align-items:center;gap:12px;border:0}
.logo .tile{width:44px;height:44px;border-radius:11px;background:var(--teal);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:19px;letter-spacing:-.5px;flex:none}
.logo .wm{line-height:1.05}
.logo .wm b{display:block;font-size:17px;font-weight:800;color:#212934;letter-spacing:-.2px}
.logo .wm span{display:block;font-size:10.5px;font-weight:700;color:var(--teal);letter-spacing:3px}
.top .ed{font-size:12.5px;color:var(--slate);text-align:right;line-height:1.35}
.top .ed{flex:none;white-space:nowrap}
.top .ed b{display:block;color:var(--navy);font-size:13px;letter-spacing:1.5px;text-transform:uppercase}
.top .ed .short{display:none}
/* Hero */
  .hero{background:var(--navy);color:#fff;position:relative;overflow:hidden}
.hero .wrap{display:grid;grid-template-columns:1.15fr .85fr;gap:28px;align-items:center;padding-top:52px;padding-bottom:52px;position:relative;z-index:1}
.hero .kicker{display:inline-block;font-size:12px;font-weight:700;letter-spacing:2.5px;text-transform:uppercase;color:#9FD3C3;margin-bottom:14px}
.hero h1{color:#fff;font-size:42px;letter-spacing:-.5px;margin-bottom:14px}
.hero h1 em{font-style:normal;color:#7CC7B0}
.hero p{color:#C9D2E3;font-size:17px;max-width:520px}
.hero .date{font-size:13px;color:#9AA7BF;margin-top:6px}
.hero svg{width:100%;height:auto;display:block}
.hero .grid-bg{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.045) 1px,transparent 1px);background-size:44px 44px;z-index:0}
/* KPI strip */
  .kpis{background:var(--teal);color:#fff}
.kpis .wrap{display:grid;grid-template-columns:repeat(4,1fr);gap:0}
.kpi{padding:20px 18px;border-left:1px solid rgba(255,255,255,.22)}
.kpi:first-child{border-left:0;padding-left:0}
.kpi b{display:block;font-size:30px;font-weight:800;line-height:1}
.kpi span{display:block;font-size:12.5px;margin-top:6px;color:#EAF6F1;line-height:1.35}
/* Sections */
  section{padding:54px 0 18px}
.sec-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:26px;border-bottom:3px solid var(--navy);padding-bottom:12px}
.sec-head .num{font-size:12px;font-weight:700;letter-spacing:2.5px;color:var(--teal);text-transform:uppercase;display:block;margin-bottom:4px}
.sec-head h2{font-size:28px}
.sec-head p{margin:0;color:var(--slate);font-size:14px;max-width:380px;text-align:right}
.intro{font-size:17px;color:var(--slate);max-width:760px;margin-bottom:34px}
/* Trends */
  .trends{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.trend{background:var(--card);border:1px solid var(--line);border-top:4px solid var(--teal);padding:24px 22px 18px;display:flex;flex-direction:column}
.trend .ico{width:56px;height:56px;background:var(--teal-soft);display:flex;align-items:center;justify-content:center;margin-bottom:16px}
.trend .ico svg{width:32px;height:32px}
.trend .n{font-size:12px;font-weight:700;letter-spacing:2px;color:var(--teal);text-transform:uppercase}
.trend h3{font-size:19px;margin:6px 0 10px}
.trend p{font-size:14.5px;color:#2D3646;margin-bottom:10px}
.trend .so{margin-top:auto;font-size:12.5px;color:var(--slate);padding-top:10px;border-top:1px dashed var(--line)}
.trend .so a{font-weight:600}
/* News */
  .news{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.news article{background:var(--card);border:1px solid var(--line);padding:22px 22px 14px}
.news article.wide{grid-column:1/-1;display:grid;grid-template-columns:1fr 280px;gap:22px;align-items:center}
.news h3{font-size:16px;color:var(--navy);display:flex;align-items:center;gap:10px;margin-bottom:10px}
.news h3 .dot{width:10px;height:10px;background:var(--teal);flex:none}
.news p{font-size:14.5px;color:#2D3646}
.news .tag{display:inline-block;font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;padding:3px 8px;background:var(--navy);color:#fff;margin-bottom:10px}
.news .tag.warn{background:var(--amber);color:#2A1E00}
/* Colombia */
  .co{background:var(--navy);color:#fff;padding:54px 0}
.co .wrap{display:grid;grid-template-columns:1fr 1fr;gap:36px;align-items:center}
.co .kicker{font-size:12px;font-weight:700;letter-spacing:2.5px;color:#9FD3C3;text-transform:uppercase;display:block;margin-bottom:10px}
.co h2{color:#fff;font-size:30px;margin-bottom:14px}
.co p{color:#C9D2E3;font-size:15.5px}
.co a{color:#9FD3C3;border-bottom-color:rgba(159,211,195,.5)}
.co .chart{background:var(--navy-2);padding:26px 26px 18px;border:1px solid rgba(255,255,255,.12)}
.co .chart .t{font-size:12.5px;letter-spacing:1.5px;text-transform:uppercase;color:#9AA7BF;font-weight:700;margin-bottom:16px}
.bar{margin-bottom:16px}
.bar .lbl{display:flex;justify-content:space-between;gap:12px;font-size:14px;margin-bottom:6px}
.bar .lbl b{font-size:22px;font-weight:800;flex:none}
.bar .trk{height:22px;background:rgba(255,255,255,.1)}
.bar .fill{height:100%;background:var(--teal)}
.bar.g .fill{background:#7CC7B0}
.co .chart .src{font-size:11.5px;color:#9AA7BF;margin-top:10px}
/* Tools */
  .tools{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.tool{background:var(--card);border:1px solid var(--line);padding:20px 20px 16px;display:flex;flex-direction:column;transition:border-color .15s}
.tool:hover{border-color:var(--teal)}
.tool .cat{font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;color:var(--teal);margin-bottom:6px}
.tool h3{font-size:17px;margin-bottom:8px}
.tool h3 a{color:var(--navy);border:0}
.tool h3 a:after{content:" ↗";font-size:13px;color:var(--teal)}
.tool .what{font-size:14px;color:#2D3646;margin-bottom:10px}
.tool .why{margin-top:auto;font-size:13px;color:var(--slate);background:var(--bg);padding:10px 12px;border-left:3px solid var(--teal)}
.tool .why b{color:var(--navy);font-weight:700}
.mentions{margin-top:22px;background:var(--card);border:1px solid var(--line);padding:18px 22px;font-size:14.5px}
.mentions b{color:var(--navy)}
.cats{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 26px}
.cats span{font-size:12.5px;font-weight:600;padding:6px 12px;background:#fff;border:1px solid var(--line);color:var(--navy)}
.cats span b{color:var(--teal);margin-left:4px}
/* Actions */
  .acts{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.act{padding:26px 24px;border:1px solid var(--line);background:var(--card)}
.act.cli{background:var(--teal-soft);border-color:#BFDDD2}
.act h3{font-size:18px;margin-bottom:12px;display:flex;align-items:center;gap:10px}
.act h3 svg{width:24px;height:24px;flex:none}
.act p{font-size:14.5px;color:#2D3646}
.act ul{margin:0;padding-left:18px;font-size:14.5px;color:#2D3646}
.act li{margin-bottom:6px}
/* CTA */
  .cta{background:var(--teal);color:#fff;padding:46px 0}
.cta .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px;flex-wrap:wrap}
.cta h2{color:#fff;font-size:26px;margin-bottom:6px}
.cta p{margin:0;color:#EAF6F1;font-size:15px;max-width:560px}
.btn{display:inline-block;background:var(--navy);color:#fff;font-weight:700;font-size:15px;padding:14px 24px;border:0;white-space:nowrap}
.btn:hover{background:var(--navy-2)}
/* Sources / footer */
  .sources ol{margin:0;padding-left:20px;font-size:14px;color:#2D3646;columns:2;column-gap:32px}
.sources li{margin-bottom:8px;break-inside:avoid}
footer{background:#fff;border-top:1px solid var(--line);padding:26px 0 34px;font-size:13px;color:var(--slate)}
footer .wrap{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
footer .note{max-width:620px}
@media (max-width:860px){
    .hero .wrap{grid-template-columns:1fr;padding-top:38px;padding-bottom:34px}
    .hero h1{font-size:32px}
    .hero svg{max-width:300px;margin:0 auto}
    .top .ed .full{display:none}.top .ed .short{display:inline}
    .top .ed b{font-size:12px;letter-spacing:1px}
    .kpi b{font-size:24px}
    .co h2{font-size:26px}
    .cta h2{font-size:22px}
    .btn{width:100%;text-align:center;padding:14px 16px;font-size:14px}
    .kpis .wrap{grid-template-columns:1fr 1fr}
    .kpi{padding:16px 14px;border-left:0;border-top:1px solid rgba(255,255,255,.22)}
    .kpi:nth-child(-n+2){border-top:0}
    .kpi:nth-child(odd){padding-left:0}
    .trends,.tools{grid-template-columns:1fr}
    .news,.acts,.co .wrap{grid-template-columns:1fr}
    .news article.wide{grid-template-columns:1fr}
    .sec-head{flex-direction:column;align-items:flex-start}
    .sec-head p{text-align:left}
    .sec-head h2{font-size:24px}
    .sources ol{columns:1}
    section{padding:40px 0 12px}
  }
@media print{
    body{background:#fff}
    .hero .grid-bg{display:none}
    section{padding:24px 0 8px}
    .cta,.btn{display:none}
    a:after{content:""}
  }
}
